{
  "summary": "FB_CraneSpeedCheck validates the three INT inputs against 0..100 with ReferenceSpeed10>0 before any arithmetic, promotes to DINT for the difference and 13*reference computations, and independently recomputes all three outputs each scan so exactly one of SyncOK/SyncBad/Invalid is TRUE.",
  "code": "FUNCTION_BLOCK FB_CraneSpeedCheck
VAR_INPUT
    LeftSpeed10      : INT;
    RightSpeed10     : INT;
    ReferenceSpeed10 : INT;
END_VAR

VAR_OUTPUT
    SyncOK  : BOOL;
    SyncBad : BOOL;
    Invalid : BOOL;
END_VAR

VAR
    Valid   : BOOL;
    DiffLR  : DINT;
    DiffSum : DINT;
    TwiceRef: DINT;
    SumLR   : DINT;
END_VAR

// Default: all outputs FALSE, then exactly one TRUE is set below
SyncOK  := FALSE;
SyncBad := FALSE;
Invalid := FALSE;

// Range validation before any subtraction or multiplication
Valid := (LeftSpeed10 >= 0) AND (LeftSpeed10 <= 100)
         AND (RightSpeed10 >= 0) AND (RightSpeed10 <= 100)
         AND (ReferenceSpeed10 > 0) AND (ReferenceSpeed10 <= 100);

IF NOT Valid THEN
    Invalid := TRUE;
ELSE
    // Promote to DINT for safe arithmetic
    DiffLR   := DINT#(LeftSpeed10) - DINT#(RightSpeed10);
    SumLR    := DINT#(LeftSpeed10) + DINT#(RightSpeed10);
    TwiceRef := DINT#(13) * DINT#(ReferenceSpeed10);
    DiffSum  := SumLR - TwiceRef;

    IF (DiffLR < 0) THEN
        DiffLR := -DiffLR;
    END_IF;
    IF (DiffSum < 0) THEN
        DiffSum := -DiffSum;
    END_IF;

    IF (DiffLR <= DINT#1) AND (DiffSum <= DINT#2) THEN
        SyncOK := TRUE;
    ELSE
        SyncBad := TRUE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK"
}
